INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_Paper_020', 'มีเหรียญสิบบาทและเหรียญห้าบาทรวมกันอยู่ 350 บาท ถ้าเหรียญสิบมีจำนวนมากกว่าเหรียญห้าอยู่ 5 เหรียญ จงหาว่ามีจำนวนเหรียญสิบทั้งหมดกี่เหรียญ', '["15 เหรียญ", "20 เหรียญ", "25 เหรียญ", "30 เหรียญ"]', '3', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด Paper

ตอบ 3) 25 เหรียญ
กำหนดให้ มีเหรียบสิบ x เหรียญ จะได้ว่ามีเหรียญสิบอยู่ 10x บาทมีเหรียญห้า x – 5 เหรียญ จะได้ว่ามีเหรีญห้าอยู่ 5 (x-5) บาท
จะได้สมการ 10x + 5(x-5) = 350
10x +5x - 25 = 350
15x = 350 + 25
x = 375/15 = 25
ดังนั้น มีเหรียญสิบเท่ากับ 25 เหรียญ', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2567', 'Paper', 0);
