INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam1_079', 'I read the . . . ., but I still can’t use the machine.', '["manual", "rule", "order", "guide"]', '1', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam1

