INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam1_098', 'We have a(n) . . . . with local stores for the supply of raw materials.', '["event", "agreement", "promotion", "lease"]', '2', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam1

