INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam2_034', 'นาง ก เดินออกจากบ้านไปทางทิศตะวันออก 5 กิโลเมตร และเดินขึ้นทิศเหนือไปอีก 12 กิโลเมตร จะถึงโรงเรียน อยากทราบว่าบ้านห่างจากโรงเรียนใกล้ที่สุดกี่กิโลเมตร', '["12 กิโลเมตร", "13 กิโลเมตร", "16 กิโลเมตร", "17 กิโลเมตร"]', '2', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam2

