INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam2_104', 'What is the synonym of “sufficient”', '["enough", "deficient", "complete", "delicious"]', '1', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam2

ตอบ 1) enough
sufficient หมายถึง เพียงพอ
