INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_019', '5 * 2 = 40
2 * 4 = 88
3 * 1 = ?', '["12", "16", "17", "33"]', '1', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

ตอบ 1) 12
จากความสัมพันธ์ (หน้า + 1 + 2หลัง)(2หลัง) = ผลลัพธ์
จะได้ [5+1 + 2(2)] (2×2) = (6+4)(4) = 10 × 4 = 40 [2+1 + 2(4)] (2×4) = (3+8)(8) = 11 × 8 = 88 ดังนั้น [3+1 + 2(1)] (2×1) = (4+2)(2) = 6 × 2 = 12', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2567', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_020', '10 * 5 = 40
3 * 7 = 25
6 * 6 = ?', '["26", "31", "36", "40"]', '2', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

ตอบ 2) 31
จากความสัมพันธ์ 3 (หน้า+หลัง) – 5 = ผลลัพธ์
จะได้ 3(10+5) – 5 = 3(15) -5 = 45 – 5 = 40
3(3+7) – 5 = 3(10) – 5 = 30 – 5 = 25
ดังนั้น 3(6+6) – 5 = 3(12) – 5 = 36 – 5 = 31', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป", "โอเปอเรชัน"]', '2567', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_021', '7 * 5 = 55
8 * 10 = 80
10 * 8 = ?', '["82", "90", "112", "120"]', '1', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

