INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_023', '5 * 9 = 180
7 * 10 = 210
4 * 8 = ?', '["96", "124", "128", "132"]', '3', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

