INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_024', 'ก้านไถนาวันละ 7 ชั่วโมง แก่นไถนาวันละ 9 ชั่วโมง ถ้าใน 1 ชั่วโมง แต่ละคนไถนาได้ 10 ตารางวา ในเวลา 10 วัน ก้านและแก่นจะช่วยกันไถนาได้ทั้งหมดกี่ไร่', '["4 ไร่", "5 ไร่", "6 ไร่", "7 ไร่"]', '1', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

ตอบ 1) 4 ไร่
ใน 1 วัน ทำงานรวมกันได้ 7 + 9 = 16 ชั่วโมง
ใน 1 วัน จะไถนาได้ 16 ชั่วโมง × 10 ตารางวา = 160 ตารางวา
ใน 10 วัน จะได้นาได้ 160 × 10 = 1,600 ตาราวา
พื้นที่ 400 ตารางวา เท่ากับ 1 ไร่
พื้นที่ 1,600 ตารางวา เท่ากับ 1,600/400 = 4 ไร่', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2567', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_025', 'กำหนดให้ n เป็นจำนวนเต็มบวกที่ซึ่ง 49^n > 7^10 จงหาว่า n ที่มีค่าน้อยที่สุดเท่ากับเท่าไร', '["5", "6", "7", "8"]', '2', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

ตอบ 2) 6
