INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_028', 'กำหนดให้ a = 4 และ b = -7 จงหาค่าของ – a – b', '["- 3", "3", "- 11", "11"]', '2', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

