INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_029', 'กำหนดให้ b < 0 ข้อใดต่อไปนี้ถูกต้อง', '["b > b^2", "–b < 0", "b + 1 > 0", "2b > 5b"]', '4', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

ตอบ 4) 2b > 5b
ทดลองแทนค่า b = -1
1. b > b^2 จะได้ -1 > (-1)^2 หรือ -1 > 1 ไม่ถูกต้อง
2. –b < 0 จะได้ -(-1) < 0 หรือ 1 < 0 ไม่ถูกต้อง
3. b + 1 > 0 จะได้ -1 + 1 > 0 หรือ 0 > 0 ไม่ถูกต้อง
4. 2b > 5b จะได้ 2(-1) > 5(-1) หรือ -1 > -5 ถูกต้อง', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2567', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_030', 'กำหนดให้ 2a + 3 = 5 และ 3a + 2b = -12 จงหาค่าของ 2a + b', '["-2.5", "-5.5", "-6", "-7.5"]', '2', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

ตอบ 2) -5.5
จาก 2a + 3 = 5
2a = 2
a = 1
แทนค่า a = 1 ใน 3a + 2b = -12
จะได้ 3(1) + 2b = -12
2b = -15
b = -7.5
