INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_e-Exam3_084', 'He finished the race in spite of . . . . illness.', '["his", "him", "he is", "himself"]', '1', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด e-Exam3

