INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_รอบพิเศษ_004', '5 * 6 = 35
3 * 2 = 9
