INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_รอบพิเศษ_007', 'ถังหนึ่งมีน้ำอยู่ในถัง 2/5 ของถัง เติมน้ำอีก 30 ลิตรจะเต็มพอดี ถังใบนี้บรรจุน้ำได้ทั้งหมดกี่ลิตร', '["45 ลิตร", "50 ลิตร", "60 ลิตร", "75 ลิตร"]', '2', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด รอบพิเศษ

ตอบ 50 ลิตร
กำหนดให้ถังใบนี้บรรจุน้ำได้ X ลิตร
