INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_รอบพิเศษ_008', 'ปัจจุบันเภาและภูมีอายุเป็นอัตราส่วน 5:6 เมื่อ 10 ปีที่แล้วมีอายุเป็นอัตราส่วน 3:4 อายุปัจจุบันของเภาและภูรวมกันเท่ากับเท่าไร', '["45 ปี", "50 ปี", "55 ปี", "60 ปี"]', '3', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด รอบพิเศษ

ตอบ 55 ปี
กำหนดให้ เมื่อ 10 ปีที่แล้ว อายุของเภาเท่ากับ 3x ปี และของภูเท่ากับ 4x ปี
เมื่อ 10 ปีที่แล้ว ปัจจุบัน
เภา 3^x^(3x + 10)
ภู 4x 4x + 10
นำอายุปัจจุบันมาตั้งสมการเทียบกับอัตราส่วน จะได้
(3x+10)/(4x+10) = 5/6
6 (3x+10) = 5 (4x+10)
18x + 60 = 20x + 50
20x – 18x = 60 -50
2x = 10
x = 10/2 = 5
จะได้ว่า อายุปัจจุบันของเภา คือ 5x = 5×5 = 25
อายุปัจจุบันของภู คือ 6x = 6×5 = 30
ดังนั้น อายุปัจจุบันของเภาและภูรวมกันเท่ากับ 25 + 30 = 55 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2567', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_รอบพิเศษ_009', 'ธีได้รับเงินเดือน 17,500 บาท รายจ่ายเป็นค่าอาหาร 20% ค่าเดินทาง 25% และส่งให้ครอบครัวอีก 2,000 บาท ส่วนที่เหลือฝากธนาคารทั้งหมด ธีเหลือเงินฝากธนาคารเดือนละกี่บาท', '["7,250 บาท", "7,500 บาท", "7,625 บาท", "7,875 บาท"]', '3', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด รอบพิเศษ

ตอบ 7,625 บาท
เงินเดือน 17,500 บาท
ค่าอาหาร 17,500 × 20/100 = 3,500 บาท
ค่าเดินทาง 17,500 × 25/100 = 4,375 บาท
ส่งให้ครอบครัว 2,000 บาท
เงินฝากธนาคาร = เงินเดือน – (ค่าอาหาร + ค่าเดินทาง + ส่งให้ครอบครัว)
= 17,500 – (3,500 + 4,375 + 2,000)
= 17,500 – 9,875
= 7,625
ดังนั้น ธีเหลือเงินฝากธนาคารเดือนละ 7,625 บาท', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2567', 'รอบพิเศษ', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2567_รอบพิเศษ_010', 'สนามฟุตบอลรูปสี่เหลี่ยมผืนผ้ามีความยาวยาวกว่าด้านกว้าง 2 เท่า อยู่ 8 เมตร ถ้าด้านกว้างเท่ากับ 80 เมตรสนามแห่งนี้จะมีความยาวรอบสนามเท่ากับกี่เมตร', '["480 เมตร", "488 เมตร", "496 เมตร", "504 เมตร"]', '3', 'ข้อสอบจริง ก.พ. ปี 2567 ชุด รอบพิเศษ

