INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1_031', 'เกษตรกรปลูกผลไม้ 4 ชนิด ได้แก่ลางสาด 1/3 ของผลไม้ทั้งหมด ลองกอง 1/4 ของผลไม้ทั้งหมด ทุเรียน 1/5 ของผลไม้ทั้งหมด ที่เหลือเป็นมังคุด 78 ต้น อยากทราบว่ามีลองกองกี่ต้น', '["72 ต้น", "90 ต้น", "104 ต้น", "120 ต้น"]', '2', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1

ตอบ 2) 90 ต้น
หาค.ร.น. ของ 3, 4 และ 5 เท่ากับ 3 × 4 × 5 = 60
สัดส่วนของผลไม้แต่ละชนิด
ลางสาด : 1/3 × 20/20 = 20/60
ลองกอง : 1/4 × 15/15 = 15/60
ทุเรียน : 1/5 × 12/12 = 12/60
เหลือส่วนของมังคุด หาได้จากสัดส่วนของจำนวนต้นไม้ทั้งหมด – ต้นลางสาด - ต้นลองกอง - ต้นทุเรียนจะได้ 60 – 20 – 15 – 12 = 13 (แต่โจทย์กำหนดว่ามีมังคุด 78 ต้น)
หาต้นไม้ทั้งหมดจาก 78/13 = 6 (แสดงว่าจำนวนที่แท้จริงมีมากกว่าสัดส่วนที่คำนวณได้ตอนแรก 6 เท่า) จะได้ว่ามีต้นไม้ทั้งหมด 60 × 6 = 360 ต้น
จะมีต้นลองกองเท่ากับ 360 × 15/60 = 90 ต้น', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2568', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1_032', 'โรงงานผลิตตุ๊กตาแห่งหนึ่งมีพนักงานชายและหญิงรวมกัน 60 คน ในแต่ละวันพนักงานชายสามารถผลิตตุ๊กตาได้ 30 ตัวต่อคน พนักงานหญิงสามารถผลิตตุ๊กตาได้ 10 ตัวต่อคน หากพนักงานชายไม่มาทำงาน 4 คน พนักงานชายที่เหลือต้องผลิตตุ๊กตาเพิ่มอีกคนละ 12 ตัวจึงจะได้เท่ากับกำลังการผลิตต่อวันตามปกติ จงหาจำนวนพนักงานหญิงของโรงงานแห่งนี้', '["14 คน", "38 คน", "46 คน", "52 คน"]', '3', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1

ตอบ 3) 46 คน
พนักงานชายไม่มา 4 คน กำลังการผลิตน้อยลงเท่ากับ 4 × 30 = 120 ตัว
จำนวนพนักงานชายที่มา = จ^ำนวนตุ๊กตาที่ต้องผลิตเพิ่มทั้งหมด = 120/12 = 10 คนจำนวนตุ๊กตาที่ต้องผลิตเพิ่มต่อคน
จะได้ว่าจำนวนพนักงานทั้งหมด = จำนวนพนักงานชายที่มาทำงาน + จำนวนพนักงานชายที่ไม่มาทำงาน + จำนวนพนักงานหญิง
60 = จำนวนพนักงานหญิง + 10 + 4
จำนวนพนักงานหญิง = 60 – 14 = 46 คน', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2568', 'e-Exam1', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1_033', '4/3 ของจำนวนหนึ่งมีค่ามากกว่า 13/15 ของจำนวนนั้นอยู่ 14 จงหาว่าจำนวนดังกล่าวมีค่าเท่าใด', '["28", "30", "33", "35"]', '2', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1

ตอบ 2) 30
