INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1_046', 'กำหนดให้ 12 + 6x + 3y +3z = 84 และ 2x – y - z = 24 ข้อใดถูกต้อง', '["2y < x", "2x > y", "x > z", "y = -z"]', '4', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1

ตอบ 4) y = -z
