INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1_107', 'Several medicines . . . . the symptoms of the illness.', '["reduce", "reduces", "reduced", "reducing"]', '1', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1

