INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1_112', 'ในกรณีที่ส่วนราชการ รัฐวิสาหกิจ หรือหน่วยงานอื่นของรัฐประสงค์จะรับโอนข้าราชการหรือลูกจ้างของ ส่วนราชการที่ถูกยุบ ให้กระทำภายในกี่วัน', '["15 วัน", "30 วัน", "60 วัน", "90 วัน"]', '2', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1

