INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1_113', 'ส่วนราชการใดขึ้นตรงต่อนายกรัฐมนตรี', '["กรมประชาสัมพันธ์", "กรมสอบสวนคดีพิเศษ", "สำนักข่าวกรองแห่งชาติ", "สำนักงานเศรษฐกิจการคลัง"]', '3', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1

