INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1 รอบชดเชย_012', 'ชื้อเสื้อกับกางเกงรวมกันราคาไม่เกิน 500 บาท โดยกางเกงแพงกว่าเสื้อ 50 บาท จะสามารถชื้อเสื้อได้แพงที่สุดในราคากี่บาท', '["200 บาท", "225 บาท", "240 บาท", "250 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1 รอบชดเชย

ตอบ 2) 225 บาท
