INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1 รอบชดเชย_013', 'นาย A หนัก 110 กิโลกรัม เดือนแรกเพิ่มขึ้น 10% เดือนที่สองเพิ่มขึ้น 5% เดือนที่สามลดลง 15% จงหาว่าเดือนที่สามนาย A หนักเท่าไร', '["108 กิโลกรัม", "110 กิโลกรัม", "116 กิโลกรัม", "127 กิโลกรัม"]', '1', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1 รอบชดเชย

ตอบ 1) 108 กิโลกรัม
เดือนแรกเท่ากับ (110 x (100+10))/100 = 121 กิโลกรัม
เดือนสองเท่ากับ (121 x (100+5))/100 = 127.5 กิโลกรัม
เดือนที่สามเท่ากับ (127.5 x (100−15))/100 = 107.99 กิโลกรัม
ดังนั้น เดือนที่สาม นาย A หนัก ≈ 108 กิโลกรัม', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2568', 'e-Exam1 รอบชดเชย', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1 รอบชดเชย_014', 'นักกีฬา 375 คน อายุเฉลี่ย 24 ปี ต่อมาถอนตัวออก 4 คน แต่ละคนมีอายุเท่ากับ 23 25 25 และ 27 ปี ต่อมารับเพิ่มอีก 9 คน อายุเฉลี่ย 17 ปี อยากทราบว่าอายุเฉลี่ยรวมของทุกคนเท่ากับกี่ปี', '["23 ปี", "24 ปี", "25 ปี", "26 ปี"]', '2', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1 รอบชดเชย

ตอบ 2) 24 ปี
จาก ค่าเฉลี่ย = ผลรวมของข้อมูล/จำนวนข้อมูล
ค่าเฉลี่ยอายุนักกีฬาที่ถอนตัว = (23+25+25+27)/4 = 100/4 = 25 ปีค่าเฉลี่ยใหม่ = (ค่าเฉลี่ยเดิม×จำนวนเดิม)−(ค่าเฉลี่ยที่ตัดออก×จำนวนที่ตัดออก)+(ค่าเฉลี่ยใหม่ ×จำนวนที่เพิ่มเข้ามา) จำนวนข้อมูลทั้งหมด
= (24×375) −(25×4) + (17×9)/(375 − 4 + 9)
= 9,053/380
= 23.82
ดังนั้น ค่าเฉลี่ยรวมของอายุนักกีฬา ≈ 24 ปี', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2568', 'e-Exam1 รอบชดเชย', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam1 รอบชดเชย_015', 'โทรไปเนเธอร์แลนด์ 2 นาทีแรก 40 บาท นาทีต่อไปนาทีละ 21 บาท โทรไปสหรัฐอเมริกา 2 นาทีแรก 20 บาท นาทีต่อไปนาทีละ 8 บาท ถ้าโทรไปทั้งสองประเทศประเทศละ 20 นาที จะเสียค่าโทรศัพท์ต่างกันกี่บาท', '["234 บาท", "254 บาท", "260 บาท", "267 บาท"]', '2', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam1 รอบชดเชย

