INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam2_077', 'Computer teaching . . . . face to face teaching.', '["as well as", "as good as", "well", "good"]', '2', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam2

