INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam3_021', 'ถ้า a * b = ab – a แล้ว 3 * ( 2 * 6 ) มีค่าเท่าใด', '["15", "27", "28", "32"]', '2', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam3

ตอบ 2) 27
