INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam3_024', '32^(x+1) = 128 จงหาค่าของ x', '["0.4", "0.6", "0.75", "1.33"]', '1', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam3

ตอบ 1) 0.4
จาก 32 = 2^5 และ 128 = 2^7
จะได้ (2^5)^(x+1) = 2^7
2^(5x+5) = 2^7
พิจารณาเฉพาะเลขยกกำลัง
5x + 5 = 7
5x = 2
x = 2/5 = 0.4', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2568', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam3_025', '2^3 + 2^(-3) มีค่าตรงกับข้อใด', '["0", "1", "9/8", "65/8"]', '4', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam3

ตอบ 4) 65/8
จากสมบัติเลขยกกำลัง a^(-n) = 1/a^n
จะได้ 2^3 + 1/2^3 = 8 + 1/8
= [8 × 8/8] + 1/8
= 64/8 + 1/8
= 65/8', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2568', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam3_026', 'กำหนดให้ 3^x + 3^x + 3^x = 243 จงหาค่าของ x', '["2", "3", "4", "5"]', '3', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam3

ตอบ 3) 4
กำหนดให้ 3^x = Y
จะได้ Y + Y + Y = 243
3Y = 243
Y = 243/3 = 81
จาก 81 = 3^4 และ 3^x = Y
จะได้ว่า Y = 3^x = 3^4
ดังนั้น x = 4', 'ความสามารถในการคิดวิเคราะห์', 'กพ ภาค ก', 0, 'ความสามารถทั่วไป', '["คณิตศาสตร์ทั่วไป"]', '2568', 'e-Exam3', 0);
INSERT INTO questions (id, question_text, choices, correct_answer, explanation, category, subject, difficulty, skill, catalogs, exam_year, exam_set, is_custom) VALUES ('2568_e-Exam3_027', 'กำหนดให้ 64^(3x - 9) = 125^(5x - 15) จงหาค่าของ x', '["0", "1", "2", "3"]', '4', 'ข้อสอบจริง ก.พ. ปี 2568 ชุด e-Exam3

ตอบ 4) 3
จากคุณสมบัติเลขยกกำลัง a^0 = 1
